import clsx from 'clsx';
import React from 'react';

import { suggestionDetailsCSS } from './SuggestionDetails.sty.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';

export type FilterFieldSuggestionDetailsProps = WithChildren &
  StylingProps &
  DataTestId;

/**
 * The `FilterField.SuggestionDetails` can be used to render additional
 * information for a suggestion.
 */
export const SuggestionDetails = (props: FilterFieldSuggestionDetailsProps) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <div
      className={clsx(suggestionDetailsCSS, consumerClassName)}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </div>
  );
};

SuggestionDetails.displayValue = 'FilterField.SuggestionDetails';
